const shelterResults = await browserjs(tabId, () => {
  // Let's inspect the cards or list items for shelters
  // First, let's find headings or links to shelters
  const cards = Array.from(document.querySelectorAll('.shelter-card, [class*="shelter"], div[wire\\:key]')).filter(el => {
