  const shelterLinks = Array.from(document.querySelectorAll('a[href*="shelter"]')).map(a => ({
    text: a.textContent.trim(),
    href: a.href
  }));

  // Also let's extract all text blocks that look like shelter listings
  const allH = Array.from(document.querySelectorAll('h2, h3, h4, h5')).map(h => ({
    tag: h.tagName,
    text: h.textContent.trim(),
    parentText: h.parentElement?.textContent?.trim().slice(0, 300)
  }));

  return {
    shelterLinks: shelterLinks.slice(0, 20),
    headings: allH.slice(0, 30)
  };
});

