const tabId = 1148881640;

const details = await browserjs(tabId, () => {
  // Find all cards or containers around the shelter links
  const links = Array.from(document.querySelectorAll('a[href*="/shelter/"]')).filter(a => !a.textContent.includes('More'));

  return links.map(a => {
    // Find the enclosing card
    let parent = a.parentElement;
    for (let i = 0; i < 5; i++) {
      if (parent && parent.textContent.includes('miles')) break;
      if (parent && parent.parentElement) parent = parent.parentElement;
    }
    return {
      name: a.textContent.trim(),
      url: a.href,
      cardText: parent ? parent.innerText.trim() : null
    };
  });
});

